CREATE TYPE "DealType" AS ENUM ('PERCENT','FIXED','BUNDLE','TIME_BASED');
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT,"imageUrl" TEXT,"active" BOOLEAN NOT NULL DEFAULT TRUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MenuItem" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL,"name" TEXT NOT NULL,"shortName" TEXT,"receiptName" TEXT,"description" TEXT,"imageUrl" TEXT,"basePrice" BIGINT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"availableNow" BOOLEAN NOT NULL DEFAULT TRUE,"favorite" BOOLEAN NOT NULL DEFAULT FALSE,"taxable" BOOLEAN NOT NULL DEFAULT TRUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MenuItem_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT);
CREATE TABLE "MenuVariant" ("id" TEXT PRIMARY KEY,"menuItemId" TEXT NOT NULL,"name" TEXT NOT NULL,"price" BIGINT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "MenuVariant_menuItemId_fkey" FOREIGN KEY("menuItemId") REFERENCES "MenuItem"("id") ON DELETE CASCADE);
CREATE TABLE "ModifierGroup" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"required" BOOLEAN NOT NULL DEFAULT FALSE,"minSelections" INTEGER NOT NULL DEFAULT 0,"maxSelections" INTEGER NOT NULL DEFAULT 1,"allowDuplicates" BOOLEAN NOT NULL DEFAULT FALSE,"active" BOOLEAN NOT NULL DEFAULT TRUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ModifierOption" ("id" TEXT PRIMARY KEY,"modifierGroupId" TEXT NOT NULL,"name" TEXT NOT NULL,"priceDelta" BIGINT NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT TRUE,"displayOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "ModifierOption_modifierGroupId_fkey" FOREIGN KEY("modifierGroupId") REFERENCES "ModifierGroup"("id") ON DELETE CASCADE);
CREATE TABLE "MenuItemModifierGroup" ("menuItemId" TEXT NOT NULL,"modifierGroupId" TEXT NOT NULL,"displayOrder" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("menuItemId","modifierGroupId"),CONSTRAINT "MenuItemModifierGroup_menuItemId_fkey" FOREIGN KEY("menuItemId") REFERENCES "MenuItem"("id") ON DELETE CASCADE,CONSTRAINT "MenuItemModifierGroup_modifierGroupId_fkey" FOREIGN KEY("modifierGroupId") REFERENCES "ModifierGroup"("id") ON DELETE RESTRICT);
CREATE TABLE "Deal" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"receiptName" TEXT,"type" "DealType" NOT NULL,"value" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"stackable" BOOLEAN NOT NULL DEFAULT FALSE,"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "DealEligibleItem" ("dealId" TEXT NOT NULL,"menuItemId" TEXT NOT NULL,PRIMARY KEY("dealId","menuItemId"),CONSTRAINT "DealEligibleItem_dealId_fkey" FOREIGN KEY("dealId") REFERENCES "Deal"("id") ON DELETE CASCADE,CONSTRAINT "DealEligibleItem_menuItemId_fkey" FOREIGN KEY("menuItemId") REFERENCES "MenuItem"("id") ON DELETE RESTRICT);
CREATE INDEX "Category_active_displayOrder_idx" ON "Category"("active","displayOrder");
CREATE INDEX "MenuItem_categoryId_active_displayOrder_idx" ON "MenuItem"("categoryId","active","displayOrder");
CREATE INDEX "MenuItem_availableNow_idx" ON "MenuItem"("availableNow");
CREATE INDEX "MenuVariant_menuItemId_active_displayOrder_idx" ON "MenuVariant"("menuItemId","active","displayOrder");
CREATE INDEX "ModifierGroup_active_displayOrder_idx" ON "ModifierGroup"("active","displayOrder");
CREATE INDEX "ModifierOption_modifierGroupId_active_displayOrder_idx" ON "ModifierOption"("modifierGroupId","active","displayOrder");
CREATE INDEX "Deal_active_startsAt_endsAt_idx" ON "Deal"("active","startsAt","endsAt");
